# Mundora RPG (Edition) — arquivo único Streamlit
# Como rodar:
#   pip install streamlit
#   streamlit run streamlit_app.py

from __future__ import annotations
import base64
from pathlib import Path
import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(
    page_title="Mundora RPG (Edition)",
    page_icon="⚔️",
    layout="wide",
    initial_sidebar_state="collapsed",
)

_GAME_B64 = """"""


def load_html() -> str:
    here = Path(__file__).resolve().parent
    for p in (
        here / "Mundora-RPG-completo.html",
        Path.cwd() / "Mundora-RPG-completo.html",
    ):
        try:
            if p.is_file() and p.stat().st_size > 500:
                return p.read_text(encoding="utf-8", errors="replace")
        except Exception:
            pass
    return base64.b64decode(_GAME_B64.encode("ascii")).decode("utf-8", errors="replace")


def main():
    st.sidebar.title("⚔️ Mundora")
    st.sidebar.caption("RPG (Edition) · arquivo único")
    st.sidebar.markdown("---")
    st.sidebar.info(
        "Só Mundora · uma jogada · login local. "
        "Abra o painel só se precisar; o jogo roda no centro."
    )
    components.html(load_html(), height=920, scrolling=True)


if __name__ == "__main__":
    main()
